menu.event:
local recv = game.engineReceiver();
element:SetupGenericListener( recv, "rp::MsgQuestInformationResponse", "gotQuestInfo" )
element:SetupGenericListener( recv, "rp::MsgToggleBlockHudItem", "toggleBlockHudItem")
element:SetupGenericListener( recv, "rp::MsgBattlePlacementState", "placementState")

game.engineReceiver():Send( game.MsgSimpleRequest(element:GetReceiver(), game.MsgSimpleRequest_QUEST_INFO));
game.engineReceiver():Send( game.MsgRequestBattlePlacementState( ) )

textComponent.event:
component("font"):Set("rp_font_title") component("size"):Set(1.0) component("alignment"):SetInt(lua_sys.MenuTextComponent_TEXT_HCENTER_ALIGNED)
component("red"):SetFloat(1.0) component("green"):SetFloat(1.0) component("blue"):SetFloat(1.0)
component("text"):SetString("BATTLE_INSTRUCTION_PLACEMENT") component("layer"):SetString("HUD");

ninesliceComponent.event:

component("topHeight"):SetFloat( 25 );
component("bottomHeight"):SetFloat( 25 );
component("leftWidth"):SetFloat( 25 );
component("rightWidth"):SetFloat( 25 );

component("height"):SetFloat( 0 )
local w = element:GetComponent("Text"):size().x
component("width"):SetFloat( w )
component("spriteName"):Set("gfx/menu/scroll_frame")				
component("layer"):SetString("HUD")
